#include "WaterMaskData.h"

bool WaterMaskData::isWater(const String& planet, float x, float y) {
    int gridX = (int)((x + 8192) / 16384.0f * 256);
    int gridY = (int)((8192 - y) / 16384.0f * 256);
    if (gridX < 0 || gridX >= 256 || gridY < 0 || gridY >= 256) return true;

    if (planet == "corellia") return corellia_mask[gridY][gridX];
    else if (planet == "dantooine") return dantooine_mask[gridY][gridX];
    else if (planet == "dathomir") return dathomir_mask[gridY][gridX];
    else if (planet == "endor") return endor_mask[gridY][gridX];
    else if (planet == "lok") return lok_mask[gridY][gridX];
    else if (planet == "naboo") return naboo_mask[gridY][gridX];
    else if (planet == "rori") return rori_mask[gridY][gridX];
    else if (planet == "talus") return talus_mask[gridY][gridX];
    else if (planet == "tatooine") return tatooine_mask[gridY][gridX];
    else if (planet == "yavin4") return yavin4_mask[gridY][gridX];
    return false;
}

